import{_t as e,it as t,n,rt as r}from"./chunks/framework.D2cFUyj2.js";var i=JSON.parse(`{"title":"動作選單與即時預覽","description":"","frontmatter":{},"headers":[{"level":2,"title":"1. 動作選單詳解","slug":"_1-動作選單詳解","link":"#_1-動作選單詳解","children":[{"level":3,"title":"內建核心動作速查","slug":"內建核心動作速查","link":"#內建核心動作速查","children":[]},{"level":3,"title":"動作選單互動與即時篩選","slug":"動作選單互動與即時篩選","link":"#動作選單互動與即時篩選","children":[]}]},{"level":2,"title":"2. 完整搜尋視窗的結果列表互動","slug":"_2-完整搜尋視窗的結果列表互動","link":"#_2-完整搜尋視窗的結果列表互動","children":[]},{"level":2,"title":"3. QuickLook 即時預覽機制","slug":"_3-quicklook-即時預覽機制","link":"#_3-quicklook-即時預覽機制","children":[{"level":3,"title":"預覽面板不接受鍵盤輸入","slug":"預覽面板不接受鍵盤輸入","link":"#預覽面板不接受鍵盤輸入","children":[]},{"level":3,"title":"多格式預覽支援","slug":"多格式預覽支援","link":"#多格式預覽支援","children":[]},{"level":3,"title":"細節設計與避讓機制","slug":"細節設計與避讓機制","link":"#細節設計與避讓機制","children":[]}]},{"level":2,"title":"4. 外掛模組互動式與富文本預覽","slug":"_4-外掛模組互動式與富文本預覽","link":"#_4-外掛模組互動式與富文本預覽","children":[]},{"level":2,"title":"5. 第三方獨立 QuickLook 橋接（可選）","slug":"_5-第三方獨立-quicklook-橋接-可選","link":"#_5-第三方獨立-quicklook-橋接-可選","children":[]},{"level":2,"title":"6. 解除檔案佔用","slug":"_6-解除檔案佔用","link":"#_6-解除檔案佔用","children":[]},{"level":2,"title":"7. 加入我的最愛","slug":"_7-加入我的最愛","link":"#_7-加入我的最愛","children":[]},{"level":2,"title":"8. 重新命名","slug":"_8-重新命名","link":"#_8-重新命名","children":[]}],"relativePath":"zh-HK/user-guide/actions-and-preview.md","filePath":"zh-HK/user-guide/actions-and-preview.md","lastUpdated":1791112464000}`),a={name:`zh-HK/user-guide/actions-and-preview.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="動作選單與即時預覽" tabindex="-1">動作選單與即時預覽 <a class="header-anchor" href="#動作選單與即時預覽" aria-label="Permalink to “動作選單與即時預覽”">​</a></h1><p>Lertaro 既能定位檔案，也集成了快顯操作體系與即時預覽面板，讓你無需頻繁開啟檔案總管即可完成檔案的檢視、管理與分發。</p><h2 id="_1-動作選單詳解" tabindex="-1">1. 動作選單詳解 <a class="header-anchor" href="#_1-動作選單詳解" aria-label="Permalink to “1. 動作選單詳解”">​</a></h2><p>在快速視窗中，於反白的結果項目上按下 <code>Ctrl+O</code> 或 <code>→</code>，即可展開該項目的快顯動作選單；只有游標已停在搜尋詞最末端時 <code>→</code> 才會生效，因此你在修改文字較前面的內容時它絕不會搶走游標移動。相同的按鍵在內嵌卡片上也一樣有效，但限於檔案對話方塊<strong>之外</strong>；停靠在開啟/儲存/瀏覽對話方塊內的卡片完全沒有動作選單。在完整搜尋視窗中這兩個按鍵都沒有綁定：請在結果上按一下滑鼠右鍵，或按 <code>Apps</code> 鍵（<code>Shift+F10</code>），同樣能在該處開啟動作選單。</p><p>並非每一行都有選單。<strong>顯示更多</strong>行、外掛模組提供的結果、網址型我的最愛、沒有任何提供者認領的即時結果、快速視窗之外的應用程式，以及所有檔案對話方塊，都不提供動作選單；在這種行上按選單按鍵不會有任何反應，而不會開出一個空面板。</p><h3 id="內建核心動作速查" tabindex="-1">內建核心動作速查 <a class="header-anchor" href="#內建核心動作速查" aria-label="Permalink to “內建核心動作速查”">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">動作名稱</th><th style="text-align:left;">預設快速鍵</th><th style="text-align:left;">功能說明</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>開啟</strong></td><td style="text-align:left;"><code>Enter</code></td><td style="text-align:left;">使用系統預設關聯程式開啟選取的檔案或啟動應用程式。在完整搜尋視窗中，<code>Enter</code> 會一次作用於<strong>所有</strong>選取行；按兩下則只開啟被按兩下的那一行。</td></tr><tr><td style="text-align:left;"><strong>在檔案總管中定位</strong></td><td style="text-align:left;"><code>Ctrl+Enter</code></td><td style="text-align:left;">開啟檔案所在目錄，並在檔案總管中直接選取該檔案。</td></tr><tr><td style="text-align:left;"><strong>以系統管理員身分執行</strong></td><td style="text-align:left;"><code>Ctrl+Shift+Enter</code></td><td style="text-align:left;">以系統管理員權限啟動選取的程式（支援可執行檔案、捷徑、批次處理腳本等）。</td></tr><tr><td style="text-align:left;"><strong>複製完整路徑</strong></td><td style="text-align:left;"><code>Ctrl+Shift+C</code></td><td style="text-align:left;">將檔案的絕對路徑（如 <code>D:\\Projects\\app.exe</code>）複製到剪貼簿。</td></tr><tr><td style="text-align:left;"><strong>複製名稱</strong></td><td style="text-align:left;"><code>Shift+C</code></td><td style="text-align:left;">將選取的檔案或資料夾名稱複製到剪貼簿，不含路徑。</td></tr><tr><td style="text-align:left;"><strong>複製檔案</strong></td><td style="text-align:left;"><code>Ctrl+C</code></td><td style="text-align:left;">將檔案本身放入剪貼簿，可直接在檔案總管或其他目錄中貼上。</td></tr><tr><td style="text-align:left;"><strong>剪下 / 複製檔案</strong></td><td style="text-align:left;"><code>Ctrl+X</code> / <code>Ctrl+C</code></td><td style="text-align:left;">將檔案本身放入剪貼簿，可直接在檔案總管或其他目錄中貼上。搜尋框內選取了文字時，這些按鍵仍然是文字指令。</td></tr><tr><td style="text-align:left;"><strong>貼上到此處</strong></td><td style="text-align:left;"><code>Ctrl+V</code></td><td style="text-align:left;">當反白的項目是資料夾時，直接把剪貼簿中的檔案貼上至該目錄；反白的項目是檔案時，則貼上到其上層資料夾。剪貼簿必須真的帶有檔案清單，因此把文字貼進搜尋詞不受影響。</td></tr><tr><td style="text-align:left;"><strong>刪除（移入資源回收筒）</strong></td><td style="text-align:left;"><code>Delete</code></td><td style="text-align:left;">將選取的檔案或資料夾安全移至 Windows 資源回收筒。只有游標已停在搜尋詞最末端時，這個單鍵才會送到動作，而原生的資源回收筒確認對話方塊會接著出現。</td></tr><tr><td style="text-align:left;"><strong>徹底刪除</strong></td><td style="text-align:left;"><code>Shift+Delete</code></td><td style="text-align:left;">永久刪除選取的項目（會先出現原生「是否要徹底刪除？」確認，之後就無法還原）。</td></tr><tr><td style="text-align:left;"><strong>重新命名</strong></td><td style="text-align:left;">—</td><td style="text-align:left;">透過 Windows Shell 重新命名單一已存在的檔案或資料夾，對話方塊會預先選取名稱主體。</td></tr><tr><td style="text-align:left;"><strong>開啟 Windows 右鍵選單</strong></td><td style="text-align:left;">—</td><td style="text-align:left;">展開原生的 Windows 檔案總管完整快顯功能表（包含第三方軟體擴充和傳送到子選單）。</td></tr></tbody></table><h3 id="動作選單互動與即時篩選" tabindex="-1">動作選單互動與即時篩選 <a class="header-anchor" href="#動作選單互動與即時篩選" aria-label="Permalink to “動作選單互動與即時篩選”">​</a></h3><ul><li><strong>即輸即篩選</strong>：展開動作選單後，直接打字即可按動作名稱快速篩選（例如輸入 <code>copy</code> 即刻定位到所有複製相關操作）。篩選框會接管鍵盤，因此移開選取時絕不會動到你原本的搜尋詞。</li><li><strong>助記字母</strong>：每個動作都可能顯示一個反白字母。按下該字母會<strong>立刻執行該動作</strong>而不只是讓它反白，而且只在篩選框仍然為空時成立，所以你為了篩選而輸入的第一個字母絕不會被搶走。</li><li><strong>獨立搜尋框</strong>：動作選單擁有獨立且開啟後自動取得焦點的搜尋框，篩選動作不會改變主搜尋詞。切換選單層級時會清空動作篩選詞，並讓新層級的搜尋框取得焦點。</li><li><strong>浮動動作面板</strong>：快速視窗、快速啟動面板和完整搜尋視窗中的動作都會以懸浮面板顯示，並錨定在目前項目附近。快速啟動面板會暫時擴展到動作清單的完整工作高度，關閉動作選單後恢復緊湊高度。</li><li><strong>層級導覽</strong>：在帶有子選單的項目（如「傳送到」或階層式動作）上按下 <code>→</code>、<code>Tab</code> 或 <code>Enter</code> 進入下一級；按 <code>←</code> 或在過濾詞為空時按 <code>Backspace</code> 返回上一級。在巢狀選單中按 <code>Escape</code> 或按一下滑鼠右鍵會返回上一級；在根層級則關閉動作選單。</li><li><strong>導覽快速鍵依然有效</strong>：你設定的「選取下一項 / 上一項」快速鍵（預設 <code>Ctrl+N</code> / <code>Ctrl+P</code>）在動作清單內同樣會移動反白，會越過首尾循環，並跳過分隔線、標題與停用的動作。只有在你沒有把 <code>Tab</code> 綁到其中一個導覽快速鍵時，<code>Tab</code> 才會用來進入子選單。</li><li><strong>點擊空白處關閉</strong>：點擊浮動動作面板以外的區域會關閉面板。主機支援時，在動作面板開啟期間按一下其他結果的滑鼠右鍵會就地替換目前動作目標。</li><li><strong>動作快速鍵</strong>：動作面板取得焦點後即可使用提供者定義的動作快速鍵。執行後會關閉浮動面板，但完整搜尋視窗或快速啟動面板仍保持開啟。</li></ul><h2 id="_2-完整搜尋視窗的結果列表互動" tabindex="-1">2. 完整搜尋視窗的結果列表互動 <a class="header-anchor" href="#_2-完整搜尋視窗的結果列表互動" aria-label="Permalink to “2. 完整搜尋視窗的結果列表互動”">​</a></h2><p>主搜尋視窗（<code>Ctrl+F</code>）專為海量檔案管理與多維度瀏覽設計：</p><ul><li><strong>按兩下路徑欄定位</strong>：按兩下結果列表中的<strong>檔案名稱</strong>為直接開啟檔案；按兩下<strong>路徑</strong>欄則會自動開啟該檔案所在的父級資料夾。此處的按兩下只指<em>左</em>鍵；在欄標題上按兩下沒有任何作用，最大化/還原來自在視窗頂部非輸入拖曳帶上按兩下。</li><li><strong>多重選取</strong>：結果表格就是一般的 Windows 列表：<code>Ctrl</code>+按一下會加入或移除該行，<code>Shift</code>+按一下會選取一段範圍，接著按 <code>Enter</code> 會一次作用於<strong>全部</strong>選取行，而按兩下只會開啟被按兩下的那一行。在已屬於選取範圍的行上按一下右鍵會保留整個選取，而不會收合到該行。</li><li><strong>無限串流式結果載入</strong>：在搜尋大容量磁碟或數百萬項目時，結果會隨後台索引引擎的檢索即時串流式呈現在列表中，無需等待全盤掃描完畢即可隨時點擊或選取操作；附加新行時會保留你的選取與捲動位置，而真正全新的結果集會從最上方重新開始。</li><li><strong>鍵盤循環導覽</strong>：在結果第一行按 <code>↑</code> 可直接跳轉到末尾行，在最後一行按 <code>↓</code> 可回到首行。快速視窗與內嵌卡片也循相同的循環規則，尚未選取任何項目時按 <code>↑</code> 會落到最後一行，按 <code>↓</code> 則落在第一行。只有快速面板會把各分組當成一個連續列表，且<strong>不</strong>循環。</li><li><strong>水平捲動</strong>：在表格上按住 <code>Shift</code> 並轉動滑鼠滾輪，每格滾動三個欄位，這就是在窄視窗下取用最右側欄位的方法。</li><li><strong>拖曳檔案外出</strong>：任何一行都能直接拖進檔案總管、對話方塊或聊天視窗，成為真正的檔案拖放；多重選取時，拖曳其中一行會把它<strong>全部</strong>帶出去。在 Lertaro 之外放下會隱藏視窗，而拖曳進行中會延後關閉，避免拖曳游標卡住。</li><li><strong>選取數量摘要</strong>：選取多個結果時，狀態列會在結果總數旁顯示目前選取的項目數量。</li><li><strong>游標懸停預覽</strong>：滑鼠移過某一行時，已開啟的預覽面板會在<strong>不</strong>改變選取的情況下改指向該行，讓你能逐行翻看，再回到選定的那一行按 <code>Enter</code>。</li><li><strong>視窗無邊框拖曳與尺寸記憶</strong>：主視窗頂部非輸入區域可作為拖曳抓取條，滑鼠游標懸停時會有提示條淡入；手動調整的視窗寬高會自動記憶並在下次啟動時沿用。</li></ul><h2 id="_3-quicklook-即時預覽機制" tabindex="-1">3. QuickLook 即時預覽機制 <a class="header-anchor" href="#_3-quicklook-即時預覽機制" aria-label="Permalink to “3. QuickLook 即時預覽機制”">​</a></h2><p>在可預覽的結果上按下 <code>Alt+P</code>，即可在搜尋視窗旁呼出停靠的即時預覽面板，或<strong>在該行上按一下滑鼠中鍵</strong>切換同一個面板。整個內嵌視窗（不論是否停靠在檔案對話方塊）兩種手勢都無法使用，快速面板則兩者皆支援。</p><h3 id="預覽面板不接受鍵盤輸入" tabindex="-1">預覽面板不接受鍵盤輸入 <a class="header-anchor" href="#預覽面板不接受鍵盤輸入" aria-label="Permalink to “預覽面板不接受鍵盤輸入”">​</a></h3><p>該面板刻意設計成不會取得焦點：它絕不會從搜尋視窗搶走焦點，所以沒有可供輸入的地方，按 <code>Escape</code> 也不會關閉它。請用 <code>Alt+P</code> 切換，或關閉它所停靠的那個視窗來隱藏它。面板上的所有控制項——媒體播放列、捲軸、外掛模組卡片——一律只能用滑鼠操作，鍵盤焦點會完全留在原本的位置。</p><h3 id="多格式預覽支援" tabindex="-1">多格式預覽支援 <a class="header-anchor" href="#多格式預覽支援" aria-label="Permalink to “多格式預覽支援”">​</a></h3><ul><li><strong>圖片</strong>：支援 JPG、PNG、GIF、BMP、ICO 影像格式的縮放呈現。</li><li><strong>文件與文字代碼</strong>：支援 TXT、Markdown、JSON、XML、YAML、C#、Python、JS、HTML 等文字與代碼的等寬字體純文字呈現（不含語法高亮）。</li><li><strong>音訊/影片即時播放</strong>：影片檔案（MP4、M4V、WMV、AVI、MOV、MPG/MPEG）與音訊檔案（MP3、WAV、WMA、M4A、AAC）在預覽面板開啟時會<strong>自動開始播放</strong>，並配備自適應主題的迷你控制條（播放/暫停、拖曳進度、即時長度、靜音控制），切換選取項目時立即停止。</li><li><strong>資料夾結構透視</strong>：選取資料夾時，預覽面板會自動列出其前 30 個直接子項目並顯示檔案圖示與大小，自動過濾系統和隱藏檔案。</li></ul><h3 id="細節設計與避讓機制" tabindex="-1">細節設計與避讓機制 <a class="header-anchor" href="#細節設計與避讓機制" aria-label="Permalink to “細節設計與避讓機制”">​</a></h3><ul><li><strong>尺寸與邊界自適應</strong>：預覽視窗的尺寸可在<a href="./settings/general.html#_4-預覽視窗-preview-window"><strong>設定 → 一般 → 預覽視窗</strong></a>中自訂，系統會自動確保預覽視窗不會超出當前顯示器的可視工作區。</li><li><strong>停靠方位</strong>：面板停靠在其搜尋視窗的<strong>右側</strong>，只有右側放不下時才翻到左側，它不會改去較寬敞的那一邊，因此你在捲動寬視窗時它會穩固地留在原處。接著它會跟著你移動或調整尺寸的那個視窗一併移動。</li><li><strong>尺寸記憶只限本次使用期間</strong>：拖曳調整手柄或移動面板的位置會在預覽持續使用期間被記住，但搜尋視窗一旦隱藏或關閉，下次預覽就會回到設定的尺寸與停靠方位。</li><li><strong>原生彈窗自動避讓</strong>：當預覽 Office 加密文件彈出輸入密碼對話方塊時，Lertaro 會自動臨時隱藏快速視窗與預覽面板，待密碼輸入完成或彈窗關閉後自動還原。</li><li><strong>預覽視窗拖曳源</strong>：預覽面板頂部可作為拖曳源，直接將正在預覽的檔案拖入編輯器、瀏覽器或外部通訊軟體中。底部的工具列拖曳的則是面板本身。</li></ul><h2 id="_4-外掛模組互動式與富文本預覽" tabindex="-1">4. 外掛模組互動式與富文本預覽 <a class="header-anchor" href="#_4-外掛模組互動式與富文本預覽" aria-label="Permalink to “4. 外掛模組互動式與富文本預覽”">​</a></h2><p>QuickLook 除了支援本機檔案預覽，還開放了外掛模組互動擴充能力：</p><ul><li><strong>自適應深淺色富文本</strong>：基於 WebView2 與原生元件渲染，自動適配系統的深色/淺色主題，並注入高對比字型與半透明細捲軸。</li><li><strong>豐富的外掛模組卡片</strong>：支援詞典釋義卡片、即時天氣、網頁即時快照、API 偵錯資訊等複雜互動式面板。</li></ul><h2 id="_5-第三方獨立-quicklook-橋接-可選" tabindex="-1">5. 第三方獨立 QuickLook 橋接（可選） <a class="header-anchor" href="#_5-第三方獨立-quicklook-橋接-可選" aria-label="Permalink to “5. 第三方獨立 QuickLook 橋接（可選）”">​</a></h2><p>如果你已在系統中安裝了獨立的第三方開源工具 <strong>QuickLook</strong>（<a href="https://github.com/QL-Win/QuickLook" target="_blank" rel="noreferrer">GitHub 上的 QL-Win/QuickLook</a>），可以在<a href="./settings/plugins.html"><strong>設定 → 外掛模組</strong></a>中啟用內建的 <strong>QuickLook 橋接</strong> 外掛模組。</p><ul><li><strong>接管預覽</strong>：該外掛模組會透過本地具名管道連接獨立的 QuickLook 程序，並將外部預覽視窗自動吸附在 Lertaro 旁。</li><li><strong>自動回退</strong>：若第三方 QuickLook 程序未運行或已關閉，Lertaro 會回退至內建的原生預覽面板。</li></ul><h2 id="_6-解除檔案佔用" tabindex="-1">6. 解除檔案佔用 <a class="header-anchor" href="#_6-解除檔案佔用" aria-label="Permalink to “6. 解除檔案佔用”">​</a></h2><p>官方的<strong>檔案佔用解除</strong>外掛模組為已存在的檔案提供單選動作。它會列出目前正在使用該檔案的程序、PID 和可執行檔路徑，並請求這些程序釋放檔案。選取資料夾、檔案不存在或同時選取多個項目時，該動作不可用；未偵測到佔用程序時，請求釋放按鈕也會停用。視窗使用宿主主題，並在對話方塊模式下保持在搜尋視窗上方且不出現在 Alt+Tab 切換清單中，同時提供重新整理功能。</p><h2 id="_7-加入我的最愛" tabindex="-1">7. 加入我的最愛 <a class="header-anchor" href="#_7-加入我的最愛" aria-label="Permalink to “7. 加入我的最愛”">​</a></h2><p>CoreExtensions 提供<strong>加入我的最愛</strong>動作，適用於單一已存在的檔案或資料夾。該動作會開啟主題化對話方塊讓你填寫顯示名稱；如果相同路徑已經是收藏項目，動作會隱藏。</p><h2 id="_8-重新命名" tabindex="-1">8. 重新命名 <a class="header-anchor" href="#_8-重新命名" aria-label="Permalink to “8. 重新命名”">​</a></h2><p>CoreExtensions 提供<strong>重新命名</strong>動作，適用於單一已存在的檔案或資料夾。主題化對話方塊會顯示完整的目前名稱並預先選取名稱主體：例如 <code>report.pdf</code> 只選取 <code>report</code>，資料夾和沒有副檔名的名稱會全選。按 <code>Enter</code> 確認，按 <code>Esc</code> 取消。確認後由 Windows Shell 執行實際重新命名。</p>`,32)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};